begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
set local storage.allow_delete_query='true';
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values
('91000000-0000-4000-8000-000000000001','photo-a@example.test','{}'),
('91000000-0000-4000-8000-000000000002','photo-b@example.test','{}'),
('91000000-0000-4000-8000-000000000003','photo-inactive@example.test','{}');
update profiles set is_active=true where id in ('91000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000002');
insert into user_roles(user_id,role) values
('91000000-0000-4000-8000-000000000001','STAFF'),('91000000-0000-4000-8000-000000000002','STAFF'),('91000000-0000-4000-8000-000000000003','STAFF');
create temp table photo_fixture(kind text primary key,id uuid);
grant all on photo_fixture to authenticated,service_role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"91000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into photo_fixture select 'client',id from save_client(auth.uid(),null,null,'Photo','Family','+13035558910','photo-family@example.test','EMAIL',null,null);
insert into photo_fixture select 'pet',id from save_patient(null,(select id from photo_fixture where kind='client'),null,'Luna','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into photo_fixture select 'other',id from save_patient(null,(select id from photo_fixture where kind='client'),null,'Milo','Cat',null,null,'unknown',null,'unknown','unknown',null,null,null);
select is((read_patient_photo((select id from photo_fixture where kind='pet'))->>'version')::int,0,'No photo begins at version zero');
select throws_ok($$select prepare_patient_photo('92000000-0000-4000-8000-000000000001',(select id from photo_fixture where kind='pet'),0,repeat('a',64),5242881,'image/png')$$,'23514',null,'Photo byte limit enforced');
select throws_ok($$select prepare_patient_photo('92000000-0000-4000-8000-000000000001',(select id from photo_fixture where kind='pet'),0,repeat('a',64),100,'application/pdf')$$,'23514',null,'PDF is not a patient photo');
select throws_ok($$select prepare_patient_photo('92000000-0000-4000-8000-000000000001',(select id from photo_fixture where kind='pet'),0,'bad hash',100,'image/png')$$,'23514',null,'Exact digest required');
select throws_ok($$select prepare_patient_photo('92000000-0000-4000-8000-000000000004',(select id from photo_fixture where kind='pet'),0,repeat('a',64),100,'image/jpeg')$$,'23514',null,'Raw JPEG must be normalized before storage');
select lives_ok($$select prepare_patient_photo('92000000-0000-4000-8000-000000000001',(select id from photo_fixture where kind='pet'),0,repeat('a',64),100,'image/png')$$,'Uploader reserves private photo');
select lives_ok($$select prepare_patient_photo('92000000-0000-4000-8000-000000000001',(select id from photo_fixture where kind='pet'),0,repeat('a',64),100,'image/png')$$,'Prepare retry does not duplicate');
select is((select count(*) from patient_photo_uploads),1::bigint,'One immutable intent');
select throws_ok($$select prepare_patient_photo('92000000-0000-4000-8000-000000000001',(select id from photo_fixture where kind='pet'),0,repeat('b',64),100,'image/png')$$,'23514',null,'Cannot change bytes under same reservation');
select throws_ok($$select set_patient_photo('93000000-0000-4000-8000-000000000001',(select id from photo_fixture where kind='pet'),'92000000-0000-4000-8000-000000000001',0)$$,'23514',null,'Unverified document cannot become photo');
insert into storage.objects(id,bucket_id,name,metadata) select '94000000-0000-4000-8000-000000000001','patient-documents',file_path,'{"size":100,"mimetype":"image/png"}'::jsonb from patient_documents where id='92000000-0000-4000-8000-000000000001';
select throws_ok($$select verify_patient_photo_bytes('92000000-0000-4000-8000-000000000001',auth.uid(),'94000000-0000-4000-8000-000000000001',repeat('a',64),1,1)$$,'42501',null,'Browser cannot forge server byte verification');
select set_config('request.jwt.claims','{"sub":"91000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*) from patient_photo_uploads),0::bigint,'Pending upload intent belongs only to uploader');
select throws_ok($$select read_patient_photo_upload('92000000-0000-4000-8000-000000000001')$$,'42501',null,'Foreign actor cannot obtain byte reservation');
reset role;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select verify_patient_photo_bytes('92000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000001','94000000-0000-4000-8000-000000000002',repeat('a',64),1,1)$$,'23514',null,'Replacement Storage object identity rejected');
select throws_ok($$select verify_patient_photo_bytes('92000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000001','94000000-0000-4000-8000-000000000001',repeat('b',64),1,1)$$,'23514',null,'Wrong actual digest rejected');
select throws_ok($$select verify_patient_photo_bytes('92000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000001','94000000-0000-4000-8000-000000000001',repeat('a',64),4097,1)$$,'23514',null,'Server dimension limit enforced');
select lives_ok($$select verify_patient_photo_bytes('92000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000001','94000000-0000-4000-8000-000000000001',repeat('a',64),1,1)$$,'Trusted captured bytes verified');
select lives_ok($$select verify_patient_photo_bytes('92000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000001','94000000-0000-4000-8000-000000000001',repeat('a',64),1,1)$$,'Same proof retry succeeds');
select throws_ok($$select set_patient_photo('93000000-0000-4000-8000-000000000001',(select id from photo_fixture where kind='pet'),'92000000-0000-4000-8000-000000000001',0)$$,'42501',null,'Service worker cannot select chart photo');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"91000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
with removed as(delete from storage.objects where id='94000000-0000-4000-8000-000000000001' returning 1) select is((select count(*) from removed),0::bigint,'Verified pending bytes cannot be removed');
select throws_ok($$select set_patient_photo('93000000-0000-4000-8000-000000000001',(select id from photo_fixture where kind='pet'),'92000000-0000-4000-8000-000000000001',0)$$,'23514',null,'Verified bytes still require ready document');
select lives_ok($$select finalize_patient_document('92000000-0000-4000-8000-000000000001')$$,'Uploader finalizes retained file');
select throws_ok($$select set_patient_photo('93000000-0000-4000-8000-000000000001',(select id from photo_fixture where kind='other'),'92000000-0000-4000-8000-000000000001',0)$$,'23514',null,'Cross-patient photo rejected');
select is((set_patient_photo('93000000-0000-4000-8000-000000000001',(select id from photo_fixture where kind='pet'),'92000000-0000-4000-8000-000000000001',0)->>'version')::int,1,'Photo selected with expected version');
select is((set_patient_photo('93000000-0000-4000-8000-000000000001',(select id from photo_fixture where kind='pet'),'92000000-0000-4000-8000-000000000001',0)->>'version')::int,1,'Lost selection acknowledgment retry returns same receipt');
select throws_ok($$select set_patient_photo('93000000-0000-4000-8000-000000000001',(select id from photo_fixture where kind='pet'),null,1)$$,'23505',null,'Action identity cannot be reused for removal');
select throws_ok($$select set_patient_photo('93000000-0000-4000-8000-000000000002',(select id from photo_fixture where kind='pet'),null,0)$$,'PT409',null,'Stale removal cannot overwrite photo');
select set_config('request.jwt.claims','{"sub":"91000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((read_patient_photo((select id from photo_fixture where kind='pet'))->>'document_id'),'92000000-0000-4000-8000-000000000001','Current photo is shared with authorized staff');
select lives_ok($$select void_patient_document('92000000-0000-4000-8000-000000000001',2,'Incorrect identity image')$$,'Voiding identity file retains history');
select is(read_patient_photo((select id from photo_fixture where kind='pet'))->'document','null'::jsonb,'Voided original is no longer displayed');
select is((set_patient_photo('93000000-0000-4000-8000-000000000002',(select id from photo_fixture where kind='pet'),null,1)->>'version')::int,2,'Other staff can remove current photo');
select is((select updated_by from patient_photo_state where pet_id=(select id from photo_fixture where kind='pet')),auth.uid(),'Actor stamped by server');
select is((select count(*) from patient_documents),1::bigint,'Removal retains document history');
select is((select count(*) from storage.objects where id='94000000-0000-4000-8000-000000000001'),1::bigint,'Removal retains original bytes');
select throws_ok($$update patient_photo_state set document_id='92000000-0000-4000-8000-000000000001'$$,'42501',null,'Direct pointer write denied');
select throws_ok($$delete from patient_photo_actions$$,'42501',null,'Action receipts cannot be erased');
select set_config('request.jwt.claims','{"sub":"91000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is((set_patient_photo('93000000-0000-4000-8000-000000000001',(select id from photo_fixture where kind='pet'),'92000000-0000-4000-8000-000000000001',0)->>'version')::int,1,'Exact historical replay does not reselect removed image');
select is((read_patient_photo((select id from photo_fixture where kind='pet'))->>'version')::int,2,'Latest version remains after historical receipt replay');
select throws_ok($$select set_patient_photo('93000000-0000-4000-8000-000000000003',(select id from photo_fixture where kind='pet'),'92000000-0000-4000-8000-000000000001',2)$$,'23514',null,'Old intent cannot be promoted after other actions');
select set_config('request.jwt.claims','{"sub":"91000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select is((select count(*) from patient_photo_state),0::bigint,'Inactive staff cannot read photo state');
select throws_ok($$select read_patient_photo((select id from photo_fixture where kind='pet'))$$,'42501',null,'Inactive staff cannot use read RPC');
set local role anon;
select throws_ok($$select read_patient_photo(null)$$,'42501',null,'Anonymous photo read denied');
reset role;
select ok(exists(select 1 from audit_logs where table_name='patient_photo_state' and user_id='91000000-0000-4000-8000-000000000002'),'Photo changes audited');
select * from finish();
rollback;
